-- ════════════════════════════════════════════════════════════════════════
-- Zoot · Supabase schema (Kayra: schema, RPC, RLS · Steven: profiles)
-- Run in Supabase → SQL Editor, then run seed.sql (generated by `npm run seed:sql`).
-- Safe to re-run: uses IF NOT EXISTS / OR REPLACE where possible.
-- ════════════════════════════════════════════════════════════════════════

-- ── Profiles ────────────────────────────────────────────────────────────
create table if not exists public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text not null default 'Field Traveller',
  style text check (style in ('budget', 'adventurous', 'party', 'conservative')),
  avatar_seed int not null default floor(random() * 1000000),
  home_city text,
  is_verified boolean not null default false,
  xp int not null default 0 check (xp >= 0),
  cover_color text not null default '#ffcc00',
  created_at timestamptz not null default now()
);

-- New auth user → profile row.
create or replace function public.handle_new_user()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, display_name)
  values (new.id, coalesce(split_part(new.email, '@', 1), 'Field Traveller'))
  on conflict (id) do nothing;
  return new;
end $$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users
  for each row execute function public.handle_new_user();

-- ── Places catalog ──────────────────────────────────────────────────────
create table if not exists public.places (
  id text primary key,
  name text not null,
  area text not null,
  lat double precision not null,
  lng double precision not null,
  tags text[] not null default '{}',
  duration_min int not null check (duration_min > 0),
  cost_band int not null default 1 check (cost_band between 0 and 3),
  indoor boolean not null default false,
  mrt text,
  hours jsonb not null default '"24h"',
  closed_days int[] not null default '{}',
  min_window_h numeric,
  blurb text not null,
  captions text[] not null default '{}',
  safety_notes text,
  image_url text,
  image_credit text,
  embed_url text
);
alter table public.places add column if not exists image_credit text;

-- ── Trips, missions, legs ───────────────────────────────────────────────
create table if not exists public.trips (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  origin_label text not null,
  origin_lat double precision not null,
  origin_lng double precision not null,
  origin_kind text not null check (origin_kind in ('airport', 'hotel')),
  start_at timestamptz not null,
  must_return_at timestamptz not null,
  style text,
  interests text[] not null default '{}',
  energy text,
  status text not null default 'planned',
  created_at timestamptz not null default now(),
  check (must_return_at > start_at)
);

create table if not exists public.missions (
  id uuid primary key,
  trip_id uuid references public.trips (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  title text not null,
  payload_json jsonb not null,
  buffer_min int not null,
  groq_model text,
  fallback_used boolean not null default true,
  created_at timestamptz not null default now()
);

create table if not exists public.mission_legs (
  id bigint generated always as identity primary key,
  mission_id uuid not null references public.missions (id) on delete cascade,
  seq int not null,
  kind text not null check (kind in ('visit', 'return')),
  place_id text references public.places (id),
  travel_mode text not null check (travel_mode in ('walk', 'mrt', 'taxi')),
  travel_min int not null,
  stay_min int not null,
  xp int not null default 0,
  status text not null default 'pending' check (status in ('pending', 'stamped', 'skipped')),
  arrive_at timestamptz,
  depart_at timestamptz,
  unique (mission_id, seq)
);

-- ── Stamps (check-ins) ──────────────────────────────────────────────────
create table if not exists public.stamps (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  place_id text not null references public.places (id),
  mission_id uuid references public.missions (id) on delete set null,
  lat double precision not null,
  lng double precision not null,
  accuracy_m double precision,
  xp int not null default 0,
  stamped_at timestamptz not null default now()
);
create index if not exists stamps_user_place_idx on public.stamps (user_id, place_id, stamped_at);

-- ── Sidequests, bookmarks, advisories, passport pages ──────────────────
create table if not exists public.sidequests (
  id text primary key,
  place_id text not null references public.places (id),
  title text not null,
  extra_min int not null,
  xp int not null,
  active_from timestamptz,
  active_to timestamptz
);

create table if not exists public.bookmarks (
  user_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  place_id text not null references public.places (id),
  created_at timestamptz not null default now(),
  primary key (user_id, place_id)
);

create table if not exists public.advisories (
  id bigint generated always as identity primary key,
  area text not null,
  severity int not null check (severity between 1 and 4),
  source text not null,
  headline text not null,
  starts timestamptz,
  ends timestamptz
);

create table if not exists public.passport_pages (
  user_id uuid not null references auth.users (id) on delete cascade,
  city text not null,
  chop_count int not null default 0,
  cover_url text,
  primary key (user_id, city)
);

-- ── Parties (P1) ────────────────────────────────────────────────────────
create table if not exists public.parties (
  id uuid primary key default gen_random_uuid(),
  mission_template jsonb,
  place_id text references public.places (id),
  host_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  starts_at timestamptz not null,
  capacity int not null default 6 check (capacity between 2 and 20),
  status text not null default 'open' check (status in ('open', 'full', 'cancelled', 'done')),
  created_at timestamptz not null default now()
);

create table if not exists public.party_members (
  party_id uuid not null references public.parties (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  role text not null default 'member' check (role in ('host', 'member')),
  approved boolean not null default false,
  primary key (party_id, user_id)
);

create table if not exists public.messages (
  id bigint generated always as identity primary key,
  party_id uuid not null references public.parties (id) on delete cascade,
  user_id uuid not null references auth.users (id) on delete cascade default auth.uid(),
  body text not null check (length(body) between 1 and 1000),
  created_at timestamptz not null default now()
);

-- ── App config (server-side DEV_FAKE_GPS switch) ────────────────────────
create table if not exists public.app_config (
  key text primary key,
  value text not null
);
insert into public.app_config (key, value) values ('dev_fake_gps', '1')
  on conflict (key) do nothing;
-- Set to '0' before real users arrive:  update public.app_config set value = '0' where key = 'dev_fake_gps';

-- ════════════════════════════════════════════════════════════════════════
-- Row Level Security
-- ════════════════════════════════════════════════════════════════════════
alter table public.profiles enable row level security;
alter table public.places enable row level security;
alter table public.trips enable row level security;
alter table public.missions enable row level security;
alter table public.mission_legs enable row level security;
alter table public.stamps enable row level security;
alter table public.sidequests enable row level security;
alter table public.bookmarks enable row level security;
alter table public.advisories enable row level security;
alter table public.passport_pages enable row level security;
alter table public.parties enable row level security;
alter table public.party_members enable row level security;
alter table public.messages enable row level security;
alter table public.app_config enable row level security;

-- Public reads
drop policy if exists "places readable" on public.places;
create policy "places readable" on public.places for select using (true);
drop policy if exists "sidequests readable" on public.sidequests;
create policy "sidequests readable" on public.sidequests for select using (true);
drop policy if exists "advisories readable" on public.advisories;
create policy "advisories readable" on public.advisories for select using (true);
drop policy if exists "config readable" on public.app_config;
create policy "config readable" on public.app_config for select using (true);

-- Profiles: public preview, owner edits (xp is protected by the trigger below)
drop policy if exists "profiles readable" on public.profiles;
create policy "profiles readable" on public.profiles for select using (true);
drop policy if exists "profiles self insert" on public.profiles;
create policy "profiles self insert" on public.profiles for insert with check (id = auth.uid());
drop policy if exists "profiles self update" on public.profiles;
create policy "profiles self update" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());

-- Own trips / missions / legs / bookmarks / passport pages
drop policy if exists "trips own" on public.trips;
create policy "trips own" on public.trips for all using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists "missions own" on public.missions;
create policy "missions own" on public.missions for all using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists "legs own" on public.mission_legs;
create policy "legs own" on public.mission_legs for all
  using (exists (select 1 from public.missions m where m.id = mission_id and m.user_id = auth.uid()))
  with check (exists (select 1 from public.missions m where m.id = mission_id and m.user_id = auth.uid()));
drop policy if exists "bookmarks own" on public.bookmarks;
create policy "bookmarks own" on public.bookmarks for all using (user_id = auth.uid()) with check (user_id = auth.uid());
drop policy if exists "passport own" on public.passport_pages;
create policy "passport own" on public.passport_pages for all using (user_id = auth.uid()) with check (user_id = auth.uid());

-- Stamps: read own; NO insert policy — inserts only happen inside stamp_place().
drop policy if exists "stamps read own" on public.stamps;
create policy "stamps read own" on public.stamps for select using (user_id = auth.uid());

-- Parties: anyone signed in can browse; hosts manage; members request to join.
drop policy if exists "parties readable" on public.parties;
create policy "parties readable" on public.parties for select using (auth.uid() is not null);
drop policy if exists "parties host write" on public.parties;
create policy "parties host write" on public.parties for all using (host_id = auth.uid()) with check (host_id = auth.uid());
drop policy if exists "members readable" on public.party_members;
create policy "members readable" on public.party_members for select using (auth.uid() is not null);
drop policy if exists "members request" on public.party_members;
create policy "members request" on public.party_members for insert with check (user_id = auth.uid() and approved = false and role = 'member');
drop policy if exists "members host approve" on public.party_members;
create policy "members host approve" on public.party_members for update
  using (exists (select 1 from public.parties p where p.id = party_id and p.host_id = auth.uid()));
drop policy if exists "members leave" on public.party_members;
create policy "members leave" on public.party_members for delete using (user_id = auth.uid());

-- Messages: only approved members (or the host) can read and post.
create or replace function public.is_party_member(p_party uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from party_members where party_id = p_party and user_id = auth.uid() and approved)
      or exists (select 1 from parties where id = p_party and host_id = auth.uid());
$$;
drop policy if exists "messages members read" on public.messages;
create policy "messages members read" on public.messages for select using (public.is_party_member(party_id));
drop policy if exists "messages members post" on public.messages;
create policy "messages members post" on public.messages for insert with check (user_id = auth.uid() and public.is_party_member(party_id));

-- Clients may not edit their own XP directly; only the RPCs below (security definer) can.
create or replace function public.guard_profile_xp()
returns trigger language plpgsql as $$
begin
  if new.xp is distinct from old.xp and current_setting('app.xp_write', true) is distinct from 'on' then
    new.xp := old.xp;
  end if;
  return new;
end $$;
drop trigger if exists profiles_guard_xp on public.profiles;
create trigger profiles_guard_xp before update on public.profiles
  for each row execute function public.guard_profile_xp();

-- ════════════════════════════════════════════════════════════════════════
-- RPC: stamp_place — the server re-checks every check-in.
--   radius 80 m, 120 m when accuracy > 50 m; reject accuracy > 150 m unless
--   fake GPS is allowed by app_config; one stamp per place per SG day.
-- ════════════════════════════════════════════════════════════════════════
create or replace function public.stamp_place(
  p_place_id text,
  p_lat double precision,
  p_lng double precision,
  p_accuracy double precision,
  p_mission_id uuid default null,
  p_fake_gps boolean default false
) returns public.stamps
language plpgsql security definer set search_path = public as $$
declare
  v_uid uuid := auth.uid();
  v_place places;
  v_fake_ok boolean;
  v_radius double precision;
  v_dist double precision;
  v_xp int := 40;
  v_row stamps;
begin
  if v_uid is null then raise exception 'Sign in to collect stamps'; end if;
  select * into v_place from places where id = p_place_id;
  if not found then raise exception 'Unknown place %', p_place_id; end if;
  if p_lat is null or p_lng is null then raise exception 'No GPS position'; end if;

  select coalesce((select value = '1' from app_config where key = 'dev_fake_gps'), false) into v_fake_ok;
  if coalesce(p_accuracy, 999) > 150 and not (p_fake_gps and v_fake_ok) then
    raise exception 'GPS too fuzzy (±% m). Step outside or wait a moment.', round(p_accuracy);
  end if;

  v_radius := case when coalesce(p_accuracy, 999) > 50 then 120 else 80 end;
  -- Haversine distance in metres.
  v_dist := 2 * 6371000 * asin(sqrt(
    power(sin(radians(v_place.lat - p_lat) / 2), 2) +
    cos(radians(p_lat)) * cos(radians(v_place.lat)) * power(sin(radians(v_place.lng - p_lng) / 2), 2)
  ));
  if v_dist > v_radius then
    raise exception '% m away. Get within % m to stamp.', round(v_dist), v_radius;
  end if;

  if exists (
    select 1 from stamps
    where user_id = v_uid and place_id = p_place_id
      and (stamped_at at time zone 'Asia/Singapore')::date = (now() at time zone 'Asia/Singapore')::date
  ) then
    raise exception 'Already stamped here today. One chop per place per day.';
  end if;

  if p_mission_id is not null then
    select coalesce(max(l.xp), 40) into v_xp
    from mission_legs l join missions m on m.id = l.mission_id
    where l.mission_id = p_mission_id and l.place_id = p_place_id and m.user_id = v_uid;
  end if;

  insert into stamps (user_id, place_id, mission_id, lat, lng, accuracy_m, xp)
  values (v_uid, p_place_id, p_mission_id, p_lat, p_lng, p_accuracy, v_xp)
  returning * into v_row;

  perform set_config('app.xp_write', 'on', true);
  update profiles set xp = xp + v_xp where id = v_uid;

  insert into passport_pages (user_id, city, chop_count) values (v_uid, 'Singapore', 1)
  on conflict (user_id, city) do update set chop_count = passport_pages.chop_count + 1;

  return v_row;
end $$;

-- On-time return bonus (capped so it cannot be farmed).
create or replace function public.award_return_bonus(p_amount int)
returns public.profiles language plpgsql security definer set search_path = public as $$
declare v_row profiles;
begin
  if auth.uid() is null then raise exception 'Sign in first'; end if;
  perform set_config('app.xp_write', 'on', true);
  update profiles set xp = xp + least(greatest(p_amount, 0), 100) where id = auth.uid() returning * into v_row;
  return v_row;
end $$;

grant execute on function public.stamp_place(text, double precision, double precision, double precision, uuid, boolean) to authenticated;
grant execute on function public.award_return_bonus(int) to authenticated;

-- Realtime for party chat (P1).
do $$ begin
  alter publication supabase_realtime add table public.messages;
exception when others then null;
end $$;
